@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;
@group(0) @binding(2) var<storage, read> cold_table: array<u32>;
@compute @workgroup_size(16,16) fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
 if (gid.x>=GRID_WIDTH || gid.y>=GRID_HEIGHT) { return; }
 let i=gid.y*GRID_WIDTH+gid.x; grid_out[i]=grid_in[i]; }

