fn pack_voxel(mat:u32, t:u32, x:i32, y:i32, p:u32, f:u32)->u32 { return 0u; }
fn unpack_voxel(p:u32)->VoxelState { return VoxelState(0u,0u,0,0,0u,0u); }
fn exchange_thermal(a:u32,b:u32)->vec2<u32> { return vec2<u32>(0u,0u); }
@group(0) @binding(0) var<storage,read> input:array<u32>;
@group(0) @binding(1) var<storage,read_write> output:array<u32>;
@compute @workgroup_size(64) fn main(@builtin(global_invocation_id) gid:vec3<u32>) { if(gid.x<arrayLength(&input)) { output[gid.x]=input[gid.x]; } }
